citations.cypher:
CALL {
  // Total events (entry/exit + crowd) for the day
  MATCH (e:Event)
  WHERE e.timestamp_utc >= '2025-12-08T00:00:00Z' AND e.timestamp_utc < '2025-12-09T00:00:00Z'
  RETURN 'total_events' AS metric, count(e) AS value
  UNION ALL
  MATCH (ch:CrowdHour)
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN 'total_events' AS metric, sum(ch.event_count) AS value
}
UNION ALL
CALL {
  // Hourly breakdown of all events
  MATCH (e:Event)
  WHERE e.timestamp_utc >= '2025-12-08T00:00:00Z' AND e.timestamp_utc < '2025-12-09T00:00:00Z'
  WITH substring(e.timestamp_utc, 0, 13) + ':00:00Z' AS hour, count(*) AS n
  RETURN hour, n
  UNION ALL
  MATCH (ch:CrowdHour)
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN ch.hour_utc AS hour, ch.event_count AS n
}
RETURN hour, sum(n) AS count ORDER BY hour
UNION ALL
CALL {
  // Peak crowd density at NVIDIA booth
  MATCH (ch:CrowdHour {camera_location: 'DemoBooth_NVIDIA'})
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN 'peak_crowd_nvidia' AS metric, max(ch.peak_hc) AS value
}
UNION ALL
CALL {
  // Peak crowd density at Main Entrance
  MATCH (ch:CrowdHour {camera_location: 'Gate_MainEntrance'})
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN 'peak_crowd_main_entrance' AS metric, max(ch.peak_hc) AS value
}
UNION ALL
CALL {
  // Distinct active cameras
  MATCH (e:Event)-[:DETECTED_BY]->(c:Camera)
  WHERE e.timestamp_utc >= '2025-12-08T00:00:00Z' AND e.timestamp_utc < '2025-12-09T00:00:00Z'
  RETURN c.camera_id AS cid
  UNION
  MATCH (ch:CrowdHour)-[:AT_CAMERA]->(c:Camera)
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN c.camera_id AS cid
}
RETURN 'active_cameras' AS metric, count(DISTINCT cid) AS value

